import{_ as a,c as o,o as n,j as r,Y as i,t as s}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"ip-mroute | x-cmd man (ip man8) | multicast routing cache management","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ip-mroute - multicast routing cache management","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ip-mroute | x-cmd man (ip man8) | multicast routing cache management"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ip-mroute - multicast routing cache management"}]]},"headers":[],"params":{"isMan":true,"man":"ip-mroute","category":"ip man8","desc":"multicast routing cache management"},"relativePath":"ip/man8/ip-mroute.md","filePath":"ip/man8/[man].md"}'),m={name:"ip/man8/ip-mroute.md"},l={class:"visually-hidden"};function c(e,t,d,u,h,g){return n(),o("div",null,[r("h1",l,s(e.$params.man),1),t[0]||(t[0]=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ip-mroute - multicast routing cache management</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ip mroute show</strong> [ [ ** to ** ] <em>PREFIX</em> ] [ <strong>from</strong> <em>PREFIX</em> ] [ <strong>iif</strong> <em>DEVICE</em> ] [ <strong>table</strong> <em>TABLE_ID</em> ]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>mroute</strong> objects are multicast routing cache entries created by a user-level mrouting daemon (f.e. <strong>pimd</strong> or <strong>mrouted</strong> ).</p><p>Due to the limitations of the current interface to the multicast routing engine, it is impossible to change <strong>mroute</strong> objects administratively, so we can only display them. This limitation will be removed in the future.</p><h3 id="ip-mroute-show-list-mroute-cache-entries" tabindex="-1">ip mroute show - list mroute cache entries <a class="header-anchor" href="#ip-mroute-show-list-mroute-cache-entries" aria-label="Permalink to &quot;ip mroute show - list mroute cache entries&quot;">​</a></h3><dl><dt><strong>to</strong> * PREFIX** <em>(default)</em>*</dt><dd>the prefix selecting the destination multicast addresses to list.</dd><dt><strong>iif</strong> * NAME*</dt><dd>the interface on which multicast packets are received.</dd><dt><strong>from</strong> * PREFIX*</dt><dd>the prefix selecting the IP source addresses of the multicast route.</dd><dt><strong>table</strong> * TABLE_ID*</dt><dd>the table id selecting the multicast table. It can be <strong>local</strong>, <strong>main</strong>, <strong>default</strong>, <strong>all</strong> or a number.</dd></dl><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><br> <strong>ip</strong>(8)</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Original Manpage by Michail Litvak &lt;mci@owl.openwall.com&gt;</p>',13))])}const b=a(m,[["render",c]]);export{f as __pageData,b as default};
